package main
import("context";"fmt";"os";"github.com/jackc/pgx/v5")
func main(){c:=context.Background();p,e:=pgx.Connect(c,os.Getenv("DATABASE_URL"));if e!=nil{panic(e)};defer p.Close(c);var b []byte;e=p.QueryRow(c,`with j as(select id,fire_at,window_end_at from recording_jobs where recording_id=406 order by fire_at desc limit 1),x as(select c.clip_start_at,c.clip_end_at,lag(c.clip_end_at)over(order by c.clip_start_at,c.id) prev_end from recording_clips c join j on j.id=c.recording_job_id),g as(select extract(epoch from clip_start_at-prev_end) gap_seconds from x where prev_end is not null),a as(select count(*) clips,min(clip_start_at) first_start,max(clip_end_at) last_end from x) select jsonb_build_object('clips',a.clips,'first_start',a.first_start,'last_end',a.last_end,'covered_seconds',extract(epoch from(a.last_end-a.first_start))-coalesce((select sum(gap_seconds)filter(where gap_seconds>0)from g),0),'elapsed_window_seconds',extract(epoch from(a.last_end-j.fire_at)),'coverage_to_latest_pct',round((100*(extract(epoch from(a.last_end-a.first_start))-coalesce((select sum(gap_seconds)filter(where gap_seconds>0)from g),0))/nullif(extract(epoch from(a.last_end-j.fire_at)),0))::numeric,3),'positive_gap_seconds',coalesce((select sum(gap_seconds)filter(where gap_seconds>0)from g),0),'largest_gap_seconds',coalesce((select max(gap_seconds)from g),0),'gaps_over_30s',(select count(*)filter(where gap_seconds>30)from g),'gaps_over_5m',(select count(*)filter(where gap_seconds>300)from g),'overlaps',(select count(*)filter(where gap_seconds<0)from g)) from a cross join j`).Scan(&b);if e!=nil{panic(e)};fmt.Println(string(b))}
